import { NextResponse } from "next/server";
import {
  appendDevSessionEvents,
  getDevCase,
  getDevSession,
  getDevSessionEvents,
  getPostingByToken,
  saveDevSessionFiles,
} from "@/app/_lib/db";
import { jsonError } from "@/app/_lib/api-response";


// Live Work Surface (moonshot E) — append observed events + save the (editable)
// seed tree for an active session. Hand-rolled boundary coercion + bounds (the
// payload is candidate-controlled): drop unknown event kinds, cap counts/size.
// "paste" carries the paste MAGNITUDE (`size`, char count) — the in-product
// bulk-paste authenticity tell (devcase-authenticity PASTE_BULK_CHARS). Bug-ui-scan
// 2026-07-09 #1: it was previously OMITTED from this allow-list (and `size` dropped
// by the map/DB), so the -65 anti-ghostwriting penalty could never fire.
const KINDS = new Set(["open", "edit", "decision_log", "submit", "paste"]);
const MAX_EVENTS = 500; // per flush
const MAX_FILES = 50;
const MAX_FILE_BYTES = 256 * 1024;

// Session data plane tightening: the flush fires every ~8s per active candidate,
// and was re-resolving token -> posting -> case on every single call even though
// the case is frozen at publish time and can't change mid-session. Cache the
// resolved case per token so the hot path does one DB round trip instead of two,
// every flush, for every concurrent candidate.
const caseCache = new Map<string, ReturnType<typeof getDevCase>>();
function getCachedCase(token: string) {
  if (!caseCache.has(token)) {
    const posting = getPostingByToken(token);
    caseCache.set(token, posting?.caseId ? getDevCase(posting.caseId) : null);
  }
  return caseCache.get(token) ?? null;
}

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const session = getDevSession(id);
    if (!session) return NextResponse.json({ error: "session not found" }, { status: 404 });
    if (session.status !== "active") return NextResponse.json({ error: "session already submitted" }, { status: 409 });

    const body = (await request.json().catch(() => ({}))) as { events?: unknown; files?: unknown };

    let seq = 0;
    if (Array.isArray(body.events)) {
      const events = body.events
        .slice(0, MAX_EVENTS)
        .filter((e): e is Record<string, unknown> => !!e && typeof e === "object")
        .filter((e) => KINDS.has(String(e.kind)))
        .map((e) => ({
          t: Number(e.t) || 0,
          kind: String(e.kind),
          path: typeof e.path === "string" ? e.path : null,
          // Carry the paste MAGNITUDE (char count) through to the DB so the observed
          // bulk-paste authenticity penalty can fire. Candidate-controlled, so coerce
          // to a finite number (never the raw shape); null for non-paste kinds.
          size: Number.isFinite(Number(e.size)) ? Number(e.size) : null,
        }));
      seq = appendDevSessionEvents(id, events);
    }

    if (Array.isArray(body.files)) {
      const files = body.files
        .filter((f): f is Record<string, unknown> => !!f && typeof f === "object" && typeof f.path === "string")
        .slice(0, MAX_FILES)
        .map((f) => ({ path: String(f.path), contents: String(f.contents ?? "").slice(0, MAX_FILE_BYTES) }));
      saveDevSessionFiles(id, files);
    }

    // Mid-flight update reveal (LLM-era controls #5): once the session is older than
    // the case's afterMinutes, serve the requirement change with this flush response
    // and record the reveal SERVER-SIDE as a chained "perturbation" event (clients
    // can't submit that kind — see KINDS above — so the reveal moment is trustworthy).
    // Already-fired sessions keep receiving the text so a reload re-renders the banner.
    let perturbation: string | null = null;
    const kase = session.token
      ? (getCachedCase(session.token)?.case as
          | { midFlightUpdate?: { afterMinutes?: number; update?: string } }
          | null)
      : null;
    const mfu = kase?.midFlightUpdate;
    if (mfu?.update && typeof mfu.afterMinutes === "number") {
      const fired = getDevSessionEvents(id).some((e) => e.kind === "perturbation");
      const due = Date.now() - Date.parse(session.createdAt) >= mfu.afterMinutes * 60_000;
      if (fired || due) {
        if (!fired) appendDevSessionEvents(id, [{ t: Date.now(), kind: "perturbation", path: null }]);
        perturbation = mfu.update;
      }
    }

    return NextResponse.json({ ok: true, seq, perturbation });
  } catch (error) {
    return jsonError(error, "Failed to save the work session.");
  }
}

import { NextResponse } from "next/server";
import {
  appendDevSessionChat,
  appendDevSessionEvents,
  getDevCase,
  getDevSession,
  getDevSessionChat,
  getPostingByToken,
  lifecycleByPosting,
} from "@/app/_lib/db";
import { runSessionChat } from "@/app/_lib/devcase-run";
import { jsonError } from "@/app/_lib/api-response";

// LLM-era controls #2/#5 — the captured prompt channel. The candidate's assistant
// and stakeholder chats flow THROUGH the platform: every user message and model
// reply is persisted (dev_session_chat) and a chained "prompt" event marks the
// exchange in the observed process log. That makes the human<->LLM dialogue —
// how they decompose, iterate, verify, and what they ask the stakeholder —
// first-class evaluation evidence rather than something inferred from artifacts.
// Payload is candidate-controlled: coerce hard, cap sizes; the Python side fences
// the transcript as untrusted data.

const MAX_MESSAGE_CHARS = 4_000;

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const session = getDevSession(id);
    if (!session) return NextResponse.json({ error: "session not found" }, { status: 404 });
    if (session.status !== "active") return NextResponse.json({ error: "session already submitted" }, { status: 409 });

    const body = (await request.json().catch(() => ({}))) as {
      channel?: unknown;
      message?: unknown;
      currentFile?: unknown;
    };
    const channel = body.channel === "stakeholder" ? "stakeholder" : "assistant";
    const message = typeof body.message === "string" ? body.message.trim().slice(0, MAX_MESSAGE_CHARS) : "";
    if (!message) return NextResponse.json({ error: "message is required" }, { status: 400 });
    const cf = body.currentFile as { path?: unknown; contents?: unknown } | null | undefined;
    const currentFile =
      channel === "assistant" && cf && typeof cf.path === "string" && typeof cf.contents === "string"
        ? { path: cf.path, contents: cf.contents.slice(0, 64_000) }
        : null;

    const posting = session.token ? getPostingByToken(session.token) : null;
    const devCase = posting?.caseId ? getDevCase(posting.caseId) : null;
    if (!devCase?.case) return NextResponse.json({ error: "case unavailable" }, { status: 404 });

    // Transcript BEFORE this message (channel-scoped) is the model's continuity
    // context; the stored copy is the evaluation evidence.
    const transcript = getDevSessionChat(id, channel).map((m) => ({ channel: m.channel, role: m.role, text: m.text }));
    const stored = appendDevSessionChat(id, channel, "user", message);
    if (stored === 0) return NextResponse.json({ error: "chat limit reached for this session" }, { status: 429 });
    // Server-recorded, chained process event: one captured exchange on this channel.
    appendDevSessionEvents(id, [{ t: Date.now(), kind: "prompt", path: channel, size: message.length }]);

    const lang = posting ? lifecycleByPosting(posting.id)?.lang : null;
    // Trap-scan fix: this used to call `transcript.concat([{ ...message }])` here —
    // but chat.py's chat_reply() already fences the SAME message separately as
    // CANDIDATE_MESSAGE (its own prompt section, distinct from the transcript). The
    // model was receiving the candidate's newest message TWICE on every exchange:
    // extra context bloat on every turn, and a real risk of the model echoing the
    // duplicate back. Pass the transcript exactly as recorded before this message;
    // chat.py carries the new message exactly once, on its own.
    const { reply } = await runSessionChat(
      channel,
      (devCase.case as Record<string, unknown>) ?? {},
      (devCase.role as Record<string, unknown>) ?? {},
      transcript,
      message,
      currentFile,
      lang
    );
    if (reply) appendDevSessionChat(id, channel, "model", reply);
    return NextResponse.json({ reply });
  } catch (error) {
    return jsonError(error, "Failed to reach the chat channel.");
  }
}
